void mainImage( out vec4 fragColor, in vec2 fragCoord )
{    
    fragColor = texture(iChannel0,fragCoord/iResolution.xy);
}

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

vec3 hash3(vec2 p)
{
    const vec2  k1 = vec2(127.1, 311.7);
    const vec2  k2 = vec2(269.5, 183.3);
    const vec2  k3 = vec2(419.2, 371.9);
    const float scale = 43758.5453;
    vec3 q = vec3(
        dot(p, k1),
        dot(p, k2),
        dot(p, k3)
    );
    return fract(sin(q) * scale)-.5;
}

float sph(vec3 p, float f) {
    p.y -= abs(sin(iTime * 0.5 + f)) * 5.;
    p.xy *= rot(iTime);
    return length(p) - 2. - length(sin(p * 5.))*.3;
}

float sph1, sph2, sph3, id, post;

float de(vec3 p) {
    vec3 p2 = p;
    sph1 = sph(p, 1.);
    p.x -= 5.;
    sph2 = sph(p, 2.);
    p.x += 10.;
    sph3 = sph(p, 3.);
    float d = min(sph3, min(sph1, sph2));
    d = min(d, p.y + 2.5);
    id = floor(p.x / 3. - iTime * 2.);
    p.x = mod(p.x - 5. - iTime * 2., 3.) - 1.5;
    post = length(vec2(p.x, abs(p.z) - 5.)) - 0.3;
    d = min(d, post);
    return d * 0.5;
}

float det = 0.001;

vec3 normal(vec3 p) {
    vec2 e = vec2(0., det);
    return normalize(vec3(de(p + e.yxx), de(p + e.xyx), de(p + e.xxy)) - de(p));
}

vec3 march(vec3 from, vec3 dir) {
    vec2 uv = gl_FragCoord.xy / iResolution.xy;
    vec3 p = from, col = vec3(0.05);
    float d = hash(uv) * 0.1, maxdist = 100.;
    for (int b = 0; b < 5; b++) {
        for (int i = 0; i < 80; i++) {
            p += d * dir;
            d = de(p);
            if (d < det || length(p) > 30.) break;
        }
        vec3 n = normal(p);
        if (d < det) {
            dir = mix(normalize(hash3(uv + mod(iTime, 10.))), n, .5);
            d = det*2.;
            if (sph1 < 0.01) col += vec3(0.5, 0., 0.) * (1. + 2.5 * step(0.5, fract(iTime)));
            else if (sph2 < 0.01) col += vec3(0., 0.5, 0.) * (1. + 2. * step(0.5, fract(iTime + 0.25)));
            else if (sph3 < 0.01) col += vec3(0., 0., 0.5) * (1. + 2.5 * step(0.5, fract(iTime + 0.75)));
            else col += vec3(0.05);
            if (post < 0.01 && mod(id - floor(iTime * 4.), 30.) < 1.) col += vec3(1.5, 1., 0.) * 2.;
            col *= 0.55;

        }
        if (length(p) > 30.) break;
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;
    vec3 from = vec3(0., 2., -15.), dir = normalize(vec3(uv, .8));
    from.xz *= rot(floor(iTime * 0.2));
    dir.xz *= rot(floor(iTime * 0.2));
    vec3 col = march(from, dir);
    col=mix(vec3(length(col)*.7),col,.8);
    col = mix(col, texture(iChannel0, fragCoord / iResolution.xy).rgb, 0.85);
    fragColor = vec4(col, 1.0);
}
